@startuml

class Client {
  + NIN
  + TIN
  + Name
  + Address
}

class BicycleModel {
  + Name
  + Type
  + No_Gears
}

class Bicycle {
  + Number
}

class Store {
  + Name
  + Address
}

class Reservation {
  + Pickup_Day
}

class Rental {
  + Return_Date
}

Client "1" -- "*" Reservation : makes
Reservation "*" -- "1" BicycleModel : for
Reservation "*" -- "1" Store : at
Reservation "0..1" -- "0..1" Rental : results in
Bicycle "1" -- "1" BicycleModel : is a model of
Rental "*" -- "1" Bicycle : involves
Rental "*" -- "1" Store : at

@enduml

